#### 3. ไฟล์ `script.js`
```javascript
function pirateGame() {
  const treasures = [
    "เหรียญทอง 100 เหรียญ!",
    "กล่องสมบัติล้ำค่า!",
    "แผนที่สมบัติลับ!",
    "ไม่มีอะไรเลย... แค่กะโหลก!",
    "ขวดเหล้ารั่ว!"
  ];

  const random = Math.floor(Math.random() * treasures.length);
  document.getElementById("game-result").textContent = "คุณพบ: " + treasures[random] + " 🏴‍☠️";
}
```

